}

@ParameterizedTest
@MethodSource("additionProvider")
void addFromMethodSourceTest(int a, int b, int expectedSum) {
    assertThat(add(a, b)).isEqualTo(expectedSum);
}

static Stream<Arguments> additionProvider() {
    return Stream.of(
            Arguments.of(2, 3, 5),
            Arguments.of(-1, 1, 0));
}

